public int pickingNumbers(List<Integer> a) {
    int best = 0;
    for (int i = 0; i < a.size(); i++) {
        int x = a.get(i);
        int count = 0;
        for (int j = 0; j < a.size(); j++) {
            int y = a.get(j);
            if (y == x || y == x + 1) {
                count++;
            }
        }
        best = Math.max(best, count);
    }
    return best;
}

