public int pickingNumbers(List<Integer> a) {
    int[] count = new int[101];
    for (int x : a) {
        count[x]++;
    }
    int best = 0;
    for (int v = 0; v < 100; v++) {
        best = Math.max(best, count[v] + count[v + 1]);
    }
    return best;
}

